-- LAUNDRYKITA - ASSEMBLED ORACLE SQL*PLUS SCRIPT
-- Source: LAUNDRYKITAAPEX.sql + service.xml + order_detail.xml + orders.xml + customer.xml + admin(1).xml
-- Creates a fresh schema structure and imports the supplied records.
-- Run in an EMPTY schema (or after manually backing up/removing conflicting objects).
SET DEFINE OFF;
SET SERVEROUTPUT ON;

-- 1. TABLES
CREATE TABLE ADMIN (
    ID_ADMIN NUMBER(10,0) NOT NULL,
    NAME_ADMIN VARCHAR2(100) NOT NULL,
    EMAIL_ADMIN VARCHAR2(100) NOT NULL,
    PASSWORD_HASH VARCHAR2(255) NOT NULL,
    CONSTRAINT PK_ADMIN PRIMARY KEY (ID_ADMIN),
    CONSTRAINT UQ_ADMIN_EMAIL UNIQUE (EMAIL_ADMIN)
);
CREATE TABLE CUSTOMER (
    ID_CUSTOMER NUMBER(10,0) NOT NULL,
    NAME_CUSTOMER VARCHAR2(100) NOT NULL,
    EMAIL_CUSTOMER VARCHAR2(100) NOT NULL,
    PASSWORD_HASH VARCHAR2(255) NOT NULL,
    PHONE VARCHAR2(20),
    ADDRESS VARCHAR2(255),
    CONSTRAINT PK_CUSTOMER PRIMARY KEY (ID_CUSTOMER),
    CONSTRAINT UQ_CUSTOMER_EMAIL UNIQUE (EMAIL_CUSTOMER)
);
CREATE TABLE SERVICE (
    ID_SERVICE NUMBER(10,0) NOT NULL,
    SERVICE_TYPE VARCHAR2(100) NOT NULL,
    PRICE_PER_KG NUMBER(10,0) NOT NULL,
    CATEGORY VARCHAR2(50),
    DESCRIPTION VARCHAR2(255),
    CONSTRAINT PK_SERVICE PRIMARY KEY (ID_SERVICE),
    CONSTRAINT CK_SERVICE_PRICE CHECK (PRICE_PER_KG >= 0)
);
CREATE TABLE ORDERS (
    ID_ORDER NUMBER(10,0) NOT NULL,
    ID_CUSTOMER NUMBER NOT NULL,
    ID_ADMIN NUMBER,
    ORDER_DATE DATE NOT NULL,
    WEIGHT NUMBER(6,2) DEFAULT 0 NOT NULL,
    TOTAL_PRICE NUMBER(10,0) DEFAULT 0 NOT NULL,
    STATUS VARCHAR2(20) DEFAULT 'Menunggu' NOT NULL,
    DESTINATION VARCHAR2(255) NOT NULL,
    METHOD_PAYMENT VARCHAR2(20) DEFAULT 'Tunai' NOT NULL,
    STATUS_PAYMENT VARCHAR2(20) DEFAULT 'Belum Bayar' NOT NULL,
    NOTES VARCHAR2(255),
    ESTIMATED_DATE DATE,
    CONSTRAINT PK_ORDERS PRIMARY KEY (ID_ORDER),
    CONSTRAINT CK_ORDERS_STATUS CHECK (STATUS IN ('Menunggu','Diproses','Dicuci','Disetrika','Selesai')),
    CONSTRAINT CK_ORDERS_METHOD CHECK (METHOD_PAYMENT IN ('Tunai','Transfer','QRIS')),
    CONSTRAINT CK_ORDERS_PAYSTATUS CHECK (STATUS_PAYMENT IN ('Belum Bayar','Lunas')),
    CONSTRAINT CK_ORDERS_WEIGHT CHECK (WEIGHT >= 0),
    CONSTRAINT CK_ORDERS_TOTAL CHECK (TOTAL_PRICE >= 0),
    CONSTRAINT FK_ORDERS_CUSTOMER FOREIGN KEY (ID_CUSTOMER) REFERENCES CUSTOMER(ID_CUSTOMER),
    CONSTRAINT FK_ORDERS_ADMIN FOREIGN KEY (ID_ADMIN) REFERENCES ADMIN(ID_ADMIN) ON DELETE SET NULL
);
CREATE TABLE ORDER_DETAIL (
    ID_ORDER_DETAIL NUMBER(10,0) NOT NULL,
    ID_ORDER NUMBER NOT NULL,
    ID_SERVICE NUMBER NOT NULL,
    WEIGHT_KG NUMBER(6,2) NOT NULL,
    PRICE_PER_KG NUMBER(10,0) NOT NULL,
    SUBTOTAL NUMBER(10,0),
    CONSTRAINT PK_ORDER_DETAIL PRIMARY KEY (ID_ORDER_DETAIL),
    CONSTRAINT FK_DETAIL_ORDER FOREIGN KEY (ID_ORDER) REFERENCES ORDERS(ID_ORDER) ON DELETE CASCADE,
    CONSTRAINT FK_DETAIL_SERVICE FOREIGN KEY (ID_SERVICE) REFERENCES SERVICE(ID_SERVICE),
    CONSTRAINT CK_DETAIL_WEIGHT CHECK (WEIGHT_KG >= 0),
    CONSTRAINT CK_DETAIL_PRICE CHECK (PRICE_PER_KG >= 0),
    CONSTRAINT CK_DETAIL_SUBTOTAL CHECK (SUBTOTAL IS NULL OR SUBTOTAL >= 0),
    CONSTRAINT CK_DETAIL_CALC CHECK (SUBTOTAL IS NULL OR SUBTOTAL = WEIGHT_KG * PRICE_PER_KG)
);

-- 2. INDEXES
CREATE INDEX IDX_ORDERS_CUSTOMER ON ORDERS(ID_CUSTOMER);
CREATE INDEX IDX_ORDERS_ADMIN ON ORDERS(ID_ADMIN);
CREATE INDEX IDX_DETAIL_ORDER ON ORDER_DETAIL(ID_ORDER);
CREATE INDEX IDX_DETAIL_SERVICE ON ORDER_DETAIL(ID_SERVICE);

-- 3. SEQUENCES (start above the imported identifiers)
CREATE SEQUENCE SEQ_ADMIN START WITH 3 INCREMENT BY 1 NOCACHE NOCYCLE;
CREATE SEQUENCE SEQ_CUSTOMER START WITH 14 INCREMENT BY 1 NOCACHE NOCYCLE;
CREATE SEQUENCE SEQ_SERVICE START WITH 4 INCREMENT BY 1 NOCACHE NOCYCLE;
CREATE SEQUENCE SEQ_ORDERS START WITH 32 INCREMENT BY 1 NOCACHE NOCYCLE;
CREATE SEQUENCE SEQ_ORDER_DETAIL START WITH 58 INCREMENT BY 1 NOCACHE NOCYCLE;

-- 4. AUTO-ID TRIGGERS
CREATE OR REPLACE TRIGGER TRG_ADMIN_BI
BEFORE INSERT ON ADMIN FOR EACH ROW
WHEN (NEW.ID_ADMIN IS NULL)
BEGIN SELECT SEQ_ADMIN.NEXTVAL INTO :NEW.ID_ADMIN FROM DUAL; END;
/
CREATE OR REPLACE TRIGGER TRG_CUSTOMER_BI
BEFORE INSERT ON CUSTOMER FOR EACH ROW
WHEN (NEW.ID_CUSTOMER IS NULL)
BEGIN SELECT SEQ_CUSTOMER.NEXTVAL INTO :NEW.ID_CUSTOMER FROM DUAL; END;
/
CREATE OR REPLACE TRIGGER TRG_SERVICE_BI
BEFORE INSERT ON SERVICE FOR EACH ROW
WHEN (NEW.ID_SERVICE IS NULL)
BEGIN SELECT SEQ_SERVICE.NEXTVAL INTO :NEW.ID_SERVICE FROM DUAL; END;
/
CREATE OR REPLACE TRIGGER TRG_ORDERS_BI
BEFORE INSERT ON ORDERS FOR EACH ROW
WHEN (NEW.ID_ORDER IS NULL)
BEGIN SELECT SEQ_ORDERS.NEXTVAL INTO :NEW.ID_ORDER FROM DUAL; END;
/
CREATE OR REPLACE TRIGGER TRG_ORDER_DETAIL_BI
BEFORE INSERT ON ORDER_DETAIL FOR EACH ROW
WHEN (NEW.ID_ORDER_DETAIL IS NULL)
BEGIN SELECT SEQ_ORDER_DETAIL.NEXTVAL INTO :NEW.ID_ORDER_DETAIL FROM DUAL; END;
/

