SELECT 'ADMIN' AS TABLE_NAME, COUNT(*) AS ROW_COUNT FROM ADMIN
UNION ALL SELECT 'CUSTOMER', COUNT(*) FROM CUSTOMER
UNION ALL SELECT 'SERVICE', COUNT(*) FROM SERVICE
UNION ALL SELECT 'ORDERS', COUNT(*) FROM ORDERS
